/** "Adityaram Palace City Villas" crest, gold foil fill (uses #pcGold from <SvgDefs />). */
export function PalaceCityLogo({ className }) {
  return (
    <svg className={className} xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Adityaram Palace City Villas" viewBox="97 160 2841 725">
      <path fillRule="evenodd" fill="url(#pcGold)" d={PALACE_CITY_PATH} />
    </svg>
  )
}

/** "Adityaram Properties" wordmark. `tone="gold"` for the header, `tone="light"` for the footer. */
export function AdityaramLogo({ className, tone = 'gold' }) {
  const [main, accent] = tone === 'gold' ? ['url(#apGoldDeep)', '#C41E2A'] : ['#F6DC95', '#E5232A']
  return (
    <svg className={className} viewBox="36 45 2476 647" role="img" aria-label="Adityaram Properties">
      <path fillRule="evenodd" fill={main} d={AP_MAIN_PATH} />
      <path fillRule="evenodd" fill={accent} d={AP_ACCENT_PATH} />
    </svg>
  )
}
